<script setup>import { RotateCcw, Search, SlidersHorizontal } from 'lucide-vue-next'; defineProps({ modelValue: Object, locations: { type: Array, default: () => [] } }); defineEmits(['update:modelValue', 'apply', 'clear']); const statuses = [{ value: 'PENDIENTE_CONFIRMACION_TRANSPORTE', label: 'Pendiente confirmación' }, { value: 'EN_TRANSITO', label: 'En tránsito' }, { value: 'ESPERA_TECNOLOGIA', label: 'Pendiente tecnología' }, { value: 'INCIDENCIA_TRANSPORTACION', label: 'Con incidencia' }, { value: 'CERRADO', label: 'Cerrado' }]</script>
<template><form class="filter-bar" @submit.prevent="$emit('apply')"><label class="filter-search"><Search :size="17" /><input :value="modelValue.search" placeholder="Número, ticket, serial o activo" @input="$emit('update:modelValue', { ...modelValue, search: $event.target.value })" /></label><select :value="modelValue.status" @change="$emit('update:modelValue', { ...modelValue, status: $event.target.value })"><option value="">Todos los estados</option><option v-for="status in statuses" :key="status.value" :value="status.value">{{ status.label }}</option></select><select :value="modelValue.origin" @change="$emit('update:modelValue', { ...modelValue, origin: $event.target.value })"><option value="">Todos los orígenes</option><option v-for="item in locations" :key="item" :value="item">{{ item }}</option></select><select :value="modelValue.destination" @change="$emit('update:modelValue', { ...modelValue, destination: $event.target.value })"><option value="">Todos los destinos</option><option v-for="item in locations" :key="item" :value="item">{{ item }}</option></select><label class="date-field"><span>Desde</span><input type="date" :value="modelValue.from" @input="$emit('update:modelValue', { ...modelValue, from: $event.target.value })" /></label><label class="date-field"><span>Hasta</span><input type="date" :value="modelValue.to" @input="$emit('update:modelValue', { ...modelValue, to: $event.target.value })" /></label><div class="filter-actions"><button type="button" class="btn btn-ghost" @click="$emit('clear')"><RotateCcw :size="16" /> Limpiar</button><button class="btn btn-secondary"><SlidersHorizontal :size="16" /> Aplicar</button></div></form></template>
